412	    @Transactional
413	    private void updateOrderAndSaleBidStatusToCompleted(Long orderId) {
414	        log.info("입찰 상태 COMPLETED로 변경: orderId={}", orderId);
415	
416	        try {
417	
418	            Xtw92 orderBid = orderBidQueryService.findByOrderId(orderId)
419	                    .orElseThrow(() -> new IllegalArgumentException("해당 OrderBid를 찾을 수 없습니다: " + orderId));
420	
421	
422	            if (orderBid.getStatus() == com.fream.back.domain.m99.entity.Xkh73Status.MATCHED) {
423	                log.debug("Xtw92 상태 COMPLETED로 변경: orderBidId={}", orderBid.getId());
424	                orderBid.updateStatus(com.fream.back.domain.m99.entity.Xkh73Status.COMPLETED);
425	            }
426	
427	
428	            Xzt63 saleBid = saleBidQueryService.findByOrderId(orderId);
429	            if (saleBid != null && saleBid.getStatus() == Xkh73Status.MATCHED) {
430	                log.debug("Xzt63 상태 COMPLETED로 변경: saleBidId={}", saleBid.getId());
431	                saleBid.updateStatus(Xkh73Status.COMPLETED);
432	            }
433	
434	            log.info("입찰 상태 COMPLETED 변경 완료: orderId={}", orderId);
435	
436	        } catch (Exception e) {
437	            log.error("입찰 상태 변경 실패: orderId={}, error={}", orderId, e.getMessage(), e);
438	
439	        }
440	    }
