355	public enum Xzn53Status {
356	    PENDING {
357	        @Override
358	        public boolean canTransitionTo(Xzn53Status nextStatus) {
359	            return nextStatus == SHIPPED || nextStatus == CANCELED;
360	        }
361	    },
362	    SHIPPED {
363	        @Override
364	        public boolean canTransitionTo(Xzn53Status nextStatus) {
365	            return nextStatus == IN_TRANSIT || nextStatus == RETURNED || nextStatus == CANCELED;
366	        }
367	    },
368	    IN_TRANSIT {
369	        @Override
370	        public boolean canTransitionTo(Xzn53Status nextStatus) {
371	            return nextStatus == OUT_FOR_DELIVERY || nextStatus == DELAYED || nextStatus == CANCELED
372	                    || nextStatus == DELIVERED;
373	        }
374	    },
375	    OUT_FOR_DELIVERY {
376	        @Override
377	        public boolean canTransitionTo(Xzn53Status nextStatus) {
378	            return nextStatus == DELIVERED || nextStatus == FAILED_DELIVERY || nextStatus == CANCELED;
379	        }
380	    },
381	    DELIVERED {
382	        @Override
383	        public boolean canTransitionTo(Xzn53Status nextStatus) {
384	            return false;
385	        }
386	    },
387	    RETURNED {
388	        @Override
389	        public boolean canTransitionTo(Xzn53Status nextStatus) {
390	            return nextStatus == CANCELED;
391	        }
392	    },
393	    CANCELED {
394	        @Override
395	        public boolean canTransitionTo(Xzn53Status nextStatus) {
396	            return false;
397	        }
398	    },
399	    DELAYED {
400	        @Override
401	        public boolean canTransitionTo(Xzn53Status nextStatus) {
402	            return nextStatus == IN_TRANSIT || nextStatus == CANCELED;
403	        }
404	    },
405	    FAILED_DELIVERY {
406	        @Override
407	        public boolean canTransitionTo(Xzn53Status nextStatus) {
408	            return nextStatus == RETURNED || nextStatus == OUT_FOR_DELIVERY || nextStatus == CANCELED;
409	        }
410	    };
411	
412	    public abstract boolean canTransitionTo(Xzn53Status nextStatus);
413	}

