package com.fream.back.domain.m85.entity;
import com.fream.back.domain.m99.entity.Xhq12;
import com.fream.back.domain.m30.entity.Xcc44;
import com.fream.back.domain.m22.entity.Xjm45;
import com.fream.back.global.entity.Xzh80Entity;
import jakarta.persistence.*;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Getter;
import lombok.NoArgsConstructor;
@Entity @jakarta.persistence.Table(name = "sale_bid")
@Getter
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class Xzt63 extends Xzh80Entity {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;
    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "seller_id")
    private Xjm45 seller;
    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "product_size_id")
    private Xcc44 productSize;
    private int bidPrice;
    @Enumerated(EnumType.STRING)
    @Builder.Default
    private Xkh73Status status = Xkh73Status.PENDING;
    @OneToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "sale_id")
    private Xpj42 sale;
    @OneToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "order_id")
    private Xhq12 order;
    @Column(nullable = false)
    @Builder.Default
    private boolean isInstantSale = false;
    public void assignSale(Xpj42 sale) {
        this.sale = sale;
        this.status = Xkh73Status.MATCHED;
    }
    public void assignOrder(Xhq12 order) {
        this.order = order;
        this.status = Xkh73Status.MATCHED;
    }
    public void markAsInstantSale() {
        this.isInstantSale = true;
    }
    public void updateStatus(Xkh73Status newStatus) {
        this.status = newStatus;
    }
}
package com.fream.back.domain.m85.entity;
public enum Xpj42Status {
    PENDING_SHIPMENT,
    IN_TRANSIT,
    IN_INSPECTION,
    FAILED_INSPECTION,
    IN_STORAGE,
    ON_AUCTION,
    SELLING,
    SOLD,
    AUCTION_EXPIRED;
    public boolean canTransitionTo(Xpj42Status newStatus) {
        return switch (this) {
            case PENDING_SHIPMENT -> newStatus == IN_TRANSIT;
            case IN_TRANSIT -> newStatus == IN_INSPECTION;
            case IN_INSPECTION -> newStatus == FAILED_INSPECTION || newStatus == IN_STORAGE;
            case IN_STORAGE -> newStatus == ON_AUCTION || newStatus == AUCTION_EXPIRED || newStatus == SELLING;
            case ON_AUCTION -> newStatus == SOLD || newStatus == AUCTION_EXPIRED;
            case SELLING -> newStatus == SOLD || newStatus == AUCTION_EXPIRED || newStatus == ON_AUCTION;
            case SOLD, AUCTION_EXPIRED, FAILED_INSPECTION -> false;
        };
    }
}
